  var KIT_DUR = {"smallnet": 3000, "fishingrod": 3000, "flyrod": 4000, "lobstercage": 5000, "harpoon": 6000, "papyrusnet": 7000, "chisel": 60, "needle": 40, "potofwater": 15, "rake": 80, "hoe": 80, "wateringcan": 120, "steelwateringcan": 300};          // farming tools by the use (2026-10-09)
