  var GENE_NAMES = {"hp": "Health", "att": "Attack", "def": "Defence", "agi": "Agility", "knack": "Knack"};
  var NATURES = {"hardy": {"name": "Hardy", "fx": {"hp": 0.1}}, "brave": {"name": "Brave", "fx": {"att": 0.1, "def": -0.1}}, "bold": {"name": "Bold", "fx": {"def": 0.1, "att": -0.1}}, "timid": {"name": "Timid", "fx": {"dodge": 0.03, "att": -0.1}}, "jolly": {"name": "Jolly", "fx": {"dodge": 0.02, "knack": 0.02}}, "gentle": {"name": "Gentle", "fx": {"hp": 0.05, "knack": 0.02}}, "wild": {"name": "Wild", "fx": {"att": 0.15, "hp": -0.1}}, "calm": {"name": "Calm", "fx": {}}, "diligent": {"name": "Diligent", "fx": {"knack": 0.04, "att": -0.05}}, "valiant": {"name": "Valiant", "rare": true, "from": ["brave", "bold"], "fx": {"att": 0.1, "def": 0.1}, "pattern": "royal", "best": "att"}, "steadfast": {"name": "Steadfast", "rare": true, "from": ["hardy", "bold"], "fx": {"hp": 0.1, "def": 0.1}, "pattern": "stone", "best": "def"}, "fierce": {"name": "Fierce", "rare": true, "from": ["wild", "brave"], "fx": {"att": 0.2, "hp": -0.05}, "pattern": "ember", "best": "att"}, "nimble": {"name": "Nimble", "rare": true, "from": ["timid", "jolly"], "fx": {"dodge": 0.06}, "pattern": "mist", "best": "agi"}, "serene": {"name": "Serene", "rare": true, "from": ["calm", "gentle"], "fx": {"hp": 0.1, "knack": 0.04}, "pattern": "aurora", "best": "hp"}, "sage": {"name": "Sage", "rare": true, "from": ["diligent", "calm"], "fx": {"knack": 0.08}, "pattern": "starlit", "best": "knack"}, "gifted": {"name": "Gifted", "rare": true, "fx": {"knack": 0.1}, "best": "knack"}};
  var NATURE_ORDER = Object.keys(NATURES), COMMON_NATURES = NATURE_ORDER.filter(function (k) { return !NATURES[k].rare; });
