    GENE_STATS.forEach(function (k) { st[k] = Math.floor(rnd(job) * 11); });
    return { sex: rnd(job) < 0.5 ? "f" : "m", nature: COMMON_NATURES[Math.floor(rnd(job) * COMMON_NATURES.length)], stats: st };
