             natureText: natureText(g.nature), stats: GENE_STATS.map(function (k) { return { id: k, name: GENE_NAMES[k], value: g.stats[k], max: g.bred ? 15 : 10 }; }),
             total: GENE_STATS.reduce(function (a, k) { return a + g.stats[k]; }, 0), bred: !!g.bred,
