  PEOPLE.desert = {"id": "amara", "name": "Nomad Amara", "look": {"skin": 3, "hair": 1, "outfit": 3}, "says": "The sand remembers everything. So do I.", "quests": [{"id": "caravan", "name": "Water for the caravan", "text": "\"My camels are thirsty and my people are hungry. Dates, and fish from the oasis.\"", "needs": [{"bring": {"dates": 20, "tilapia": 10}}], "reward": {"coins": 2500, "xp": {"foraging": 1200, "fishing": 1200}}}, {"id": "riddle", "name": "The riddle of the Sphinx", "text": "\"She asks a question and eats the wrong answers. Give her yours.\"", "needs": [{"boss": "desert"}], "reward": {"coins": 4000, "items": {"ancientchest": 1}, "xp": {"attack": 2000}}}]};
