      if (!roomFor(s, lot.id) || stackRoom(s, lot.id) < lot.n) return no(s, "Your bag has no room for " + lot.n + " × " + ITEMS[lot.id].name.toLowerCase() + ".");
      r.lots.splice(opts.i | 0, 1);
