      var con = levelOf(s.player.skills.construction || 0);
      if (!inf && con < nx.con) return no(s, "That needs Construction level " + nx.con + " (you're " + con + ").");
      var short = Object.keys(nx.needs).filter(function (q) { return !has(s, q, nx.needs[q]); });
