             risen: risenOf(s).map(function (b) { return { id: b.id, name: who(b), kind: kindName(b), species: b.species, colour: b.colour, level: beastLevel(b), hp: risenHp(b), maxHp: risenMax(b), raised: b.raised || 1 }; }),
